def normalize_tracklist(payload):
    if not isinstance(payload, dict):
        return {"ok": False, "error": "payload must be an object with a 'tracks' list"}
    allowed = ["tracks", "allow_duplicates"]
    for key in sorted(payload):
        if key not in allowed:
            return {"ok": False, "error": "unexpected key '" + str(key) + "'"}
    if "tracks" not in payload or not isinstance(payload["tracks"], list):
        return {"ok": False, "error": "payload must be an object with a 'tracks' list"}
    allow_duplicates = False
    if "allow_duplicates" in payload:
        flag = payload["allow_duplicates"]
        if not isinstance(flag, bool):
            return {"ok": False, "error": "'allow_duplicates' must be a boolean when present"}
        allow_duplicates = flag
    tracks = []
    index = 0
    for entry in payload["tracks"]:
        parsed = parse_track(entry)
        if not parsed["ok"]:
            return {"ok": False, "error": "track " + str(index + 1) + ": " + parsed["error"]}
        tracks.append(parsed["track"])
        index = index + 1
    if not allow_duplicates:
        seen = []
        position = 0
        for track in tracks:
            pair = (track["artist"].lower(), track["title"].lower())
            if pair in seen:
                return {"ok": False, "error": "duplicate track " + str(position + 1)}
            seen.append(pair)
            position = position + 1
    output_tracks = []
    number = 0
    for track in tracks:
        number = number + 1
        if number < 10:
            track_id = "T0" + str(number)
        else:
            track_id = "T" + str(number)
        output_tracks.append({"id": track_id, "title": track["title"], "artist": track["artist"], "seconds": track["seconds"], "explicit": track["explicit"], "clock": format_clock(track["seconds"])})
    total = 0
    for track in tracks:
        total = total + track["seconds"]
    return {"ok": True, "count": len(tracks), "total_seconds": total, "total_clock": format_clock(total), "tracks": output_tracks}

