def sequence_playlist(payload):
    if not isinstance(payload, dict):
        return normalize_tracklist(payload)
    allowed = ["tracks", "order", "allow_duplicates"]
    for key in sorted(payload):
        if key not in allowed:
            return {"ok": False, "error": "unexpected key '" + str(key) + "'"}
    order = "artist"
    if "order" in payload:
        order = payload["order"]
        if order != "artist" and order != "duration":
            return {"ok": False, "error": "'order' must be 'artist' or 'duration'"}
    sub = {"tracks": payload["tracks"] if "tracks" in payload else None}
    if "allow_duplicates" in payload:
        sub["allow_duplicates"] = payload["allow_duplicates"]
    base = normalize_tracklist(sub)
    if not base["ok"]:
        return base
    tracks = base["tracks"]
    if order == "artist":
        ordered = sorted(tracks, key=lambda t: t["artist"].lower())
    else:
        ordered = sorted(tracks, key=lambda t: t["seconds"])
    return {"ok": True, "order": order, "count": base["count"], "total_seconds": base["total_seconds"], "tracks": ordered}

